import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { MatSnackBarModule } from '@angular/material/snack-bar';
import { ActivatedRoute, convertToParamMap, provideRouter, Router } from '@angular/router';
import { BookingService } from '../core/booking.service';
import { AUDITORIUM } from '../core/seat-layout';
import { Checkout } from './checkout';

describe('Checkout', () => {
  const q = (el: HTMLElement, id: string) => el.querySelector<HTMLElement>(`[data-testid="${id}"]`);

  function setup() {
    sessionStorage.clear();
    TestBed.configureTestingModule({
      imports: [Checkout, MatSnackBarModule],
      providers: [
        provideRouter([]),
        provideHttpClient(),
        provideHttpClientTesting(),
        { provide: ActivatedRoute, useValue: { snapshot: { paramMap: convertToParamMap({ id: '1' }) } } },
      ],
    });
    const booking = TestBed.inject(BookingService);
    booking.open(1);
    booking.toggle(AUDITORIUM[6].middle[7]);
    booking.toggle(AUDITORIUM[14].middle[0]);
    const fixture = TestBed.createComponent(Checkout);
    fixture.detectChanges();
    return { fixture, booking, el: fixture.nativeElement as HTMLElement };
  }

  function type(el: HTMLElement, id: string, value: string) {
    const input = q(el, id) as HTMLInputElement;
    input.value = value;
    input.dispatchEvent(new Event('input'));
  }

  it('shows the total and no messages initially', () => {
    const { el } = setup();
    expect(q(el, 'pay-button')!.textContent!.trim()).toBe('Pay 121.00 PLN');
    expect(q(el, 'first-name-error')).toBeNull();
    expect(q(el, 'first-name-label')!.textContent!.trim()).toBe('First name *');
    expect(q(el, 'phone-label')!.textContent!.trim()).toBe('Phone number');
  });

  it('shows all messages on an invalid pay and sends nothing', async () => {
    const { fixture, el } = setup();
    q(el, 'pay-button')!.click();
    await fixture.whenStable();
    expect(q(el, 'first-name-error')!.textContent).toBe('First name is required');
    expect(q(el, 'confirm-email-error')!.textContent).toBe('Confirm email is required');
    expect(q(el, 'phone-error')).toBeNull();
    expect(q(el, 'terms-error')!.textContent).toBe('You must accept the terms and conditions');
    TestBed.inject(HttpTestingController).expectNone('http://localhost:3000/reservations');
  });

  it('validates as the customer types after leaving a field', async () => {
    const { fixture, el } = setup();
    type(el, 'email-input', 'a@b');
    q(el, 'email-input')!.dispatchEvent(new Event('blur'));
    type(el, 'confirm-email-input', 'a@b.c');
    q(el, 'confirm-email-input')!.dispatchEvent(new Event('blur'));
    await fixture.whenStable();
    expect(q(el, 'email-error')!.textContent).toBe('Enter a valid email address');
    expect(q(el, 'confirm-email-error')!.textContent).toBe('Email addresses do not match');
    type(el, 'email-input', 'a@b.c');
    await fixture.whenStable();
    expect(q(el, 'email-error')).toBeNull();
    expect(q(el, 'confirm-email-error')).toBeNull();
  });

  it('pays a valid form and marks the booking paid', async () => {
    const { fixture, booking, el } = setup();
    const navigate = vi.spyOn(TestBed.inject(Router), 'navigateByUrl').mockResolvedValue(true);
    type(el, 'first-name-input', 'Anna');
    type(el, 'last-name-input', 'Kowalska');
    type(el, 'email-input', 'anna@example.com');
    type(el, 'confirm-email-input', 'anna@example.com');
    type(el, 'phone-input', '123456789');
    (el.querySelector('[data-testid="terms-checkbox"] input') as HTMLInputElement).click();
    await fixture.whenStable();
    q(el, 'pay-button')!.click();
    await fixture.whenStable();
    expect(q(el, 'pay-button')!.textContent!.trim()).toBe('Processing…');
    const req = TestBed.inject(HttpTestingController).expectOne('http://localhost:3000/reservations');
    expect(req.request.body).toEqual({
      screeningId: 1,
      seats: ['R7C12', 'R15C5', 'R15C6'],
      customer: { firstName: 'Anna', lastName: 'Kowalska', email: 'anna@example.com', phone: '123456789' },
      totalPrice: 121,
    });
    req.flush({ id: 1 });
    expect(booking.booking()?.paid).toBe(true);
    expect(booking.booking()?.email).toBe('anna@example.com');
    expect(navigate).toHaveBeenCalledWith('/confirmation');
  });
});

import { TestBed } from '@angular/core/testing';
import { BookingService } from './booking.service';
import { AUDITORIUM } from './seat-layout';

describe('BookingService', () => {
  const seats = AUDITORIUM.flatMap((r) => r.middle).filter((i) => !i.couch);
  const couch = AUDITORIUM[14].middle[0];
  let service: BookingService;

  beforeEach(() => {
    sessionStorage.clear();
    TestBed.configureTestingModule({});
    service = TestBed.inject(BookingService);
    service.open(1);
  });

  it('selects and deselects, and counts a couch as 2', () => {
    service.toggle(seats[0]);
    service.toggle(couch);
    expect(service.seatCount()).toBe(3);
    service.toggle(couch);
    service.toggle(seats[0]);
    expect(service.seatCount()).toBe(0);
  });

  it('refuses to exceed 10 seats but still deselects', () => {
    for (let i = 0; i < 9; i++) service.toggle(seats[i]);
    expect(service.toggle(couch)).toBe('limit');
    expect(service.seatCount()).toBe(9);
    expect(service.toggle(seats[9])).toBe('ok');
    expect(service.toggle(seats[10])).toBe('limit');
    service.toggle(seats[0]);
    expect(service.seatCount()).toBe(9);
  });

  it('persists to sessionStorage and starts a new booking for another screening', () => {
    service.toggle(seats[0]);
    expect(JSON.parse(sessionStorage.getItem('cinescope.booking')!).seats).toEqual([seats[0].key]);
    service.open(1);
    expect(service.seatCount()).toBe(1);
    service.open(2);
    expect(service.seatCount()).toBe(0);
  });

  it('sums the total', () => {
    service.toggle(seats[0]);
    service.toggle(couch);
    expect(service.total()).toBe(25 + 89);
  });
});

import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter } from '@angular/router';
import { toIso, startOfToday } from '../core/dates';
import { MovieList } from './movie-list';

describe('MovieList', () => {
  const base = 'http://localhost:3000';
  const q = (el: HTMLElement, id: string) => [...el.querySelectorAll<HTMLElement>(`[data-testid="${id}"]`)];

  function setup() {
    TestBed.configureTestingModule({
      imports: [MovieList],
      providers: [provideRouter([]), provideHttpClient(), provideHttpClientTesting(), provideNativeDateAdapter()],
    });
    const fixture = TestBed.createComponent(MovieList);
    fixture.detectChanges();
    return { fixture, http: TestBed.inject(HttpTestingController), el: fixture.nativeElement as HTMLElement };
  }

  it('shows loading, then cards with time-ordered screenings for today', async () => {
    const { fixture, http, el } = setup();
    expect(q(el, 'movies-loading').length).toBe(1);
    expect(q(el, 'movie-card').length).toBe(0);
    const today = toIso(startOfToday());
    http.expectOne(`${base}/movies`).flush([
      { id: 1, title: 'A', genre: 'Drama', runtimeMinutes: 128, format: 'PL dubbing' },
      { id: 2, title: 'B', genre: 'Sci-Fi', runtimeMinutes: 90, format: 'PL subtitles' },
    ]);
    http.expectOne(`${base}/screenings`).flush([
      { id: 5, movieId: 1, date: today, time: '20:00', occupiedSeats: [] },
      { id: 4, movieId: 1, date: today, time: '16:00', occupiedSeats: [] },
      { id: 6, movieId: 2, date: '2020-01-01', time: '10:00', occupiedSeats: [] },
    ]);
    await fixture.whenStable();
    expect(q(el, 'movies-loading').length).toBe(0);
    expect(q(el, 'movie-card').length).toBe(1);
    expect(q(el, 'movie-runtime')[0].textContent!.trim()).toBe('128 min');
    expect(q(el, 'screening-button').map((b) => b.textContent!.trim())).toEqual(['16:00', '20:00']);
    expect(q(el, 'day-button').length).toBe(5);
    expect(q(el, 'day-button')[0].textContent!.trim()).toBe('Today');
    expect(q(el, 'day-button')[0].dataset['selected']).toBe('true');
  });

  it('shows an error with Retry, then the empty state', async () => {
    const { fixture, http, el } = setup();
    http.expectOne(`${base}/movies`).flush('x', { status: 500, statusText: 'err' });
    await fixture.whenStable();
    expect(q(el, 'movies-error')[0].textContent).toContain('Failed to load movies');
    q(el, 'movies-retry-button')[0].click();
    await fixture.whenStable();
    expect(q(el, 'movies-loading').length).toBe(1);
    http.expectOne(`${base}/movies`).flush([]);
    http.match(`${base}/screenings`).filter((r) => !r.cancelled).forEach((r) => r.flush([]));
    await fixture.whenStable();
    expect(q(el, 'movies-empty')[0].textContent).toContain('No screenings on this day');
  });
});

import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { provideRouter } from '@angular/router';
import { MatSnackBarModule } from '@angular/material/snack-bar';
import { SeatSelection } from './seat-selection';

describe('SeatSelection', () => {
  async function setup() {
    sessionStorage.clear();
    TestBed.configureTestingModule({
      imports: [SeatSelection, MatSnackBarModule],
      providers: [provideRouter([]), provideHttpClient(), provideHttpClientTesting()],
    });
    const fixture = TestBed.createComponent(SeatSelection);
    const http = TestBed.inject(HttpTestingController);
    http
      .expectOne('http://localhost:3000/screenings/')
      .flush({ id: 1, movieId: 1, date: '2026-09-15', time: '16:00', occupiedSeats: ['R3C7', 'R15C5', 'R15C6'] });
    http
      .expectOne('http://localhost:3000/movies/1')
      .flush({ id: 1, title: 'X', genre: 'Drama', runtimeMinutes: 100, format: 'PL dubbing' });
    await fixture.whenStable();
    return fixture;
  }
  const q = (el: HTMLElement, id: string) => [...el.querySelectorAll<HTMLElement>(`[data-testid="${id}"]`)];

  it('renders the auditorium', async () => {
    const fixture = await setup();
    const el = fixture.nativeElement as HTMLElement;
    expect(q(el, 'seat').length).toBe(296);
    expect(q(el, 'couch').length).toBe(12);
    expect(q(el, 'aisle').length).toBe(30);
    expect(q(el, 'seat-row').length).toBe(15);
    expect(q(el, 'row-label-left').length).toBe(15);
    expect(q(el, 'seat-map-subtitle')[0].textContent!.trim()).toBe('Show Date: Tuesday 15 Sep 16:00');
    const states = new Set(q(el, 'seat').map((s) => s.dataset['state']));
    expect(states).toEqual(new Set(['available', 'unavailable', 'accessible']));
    const row15 = q(el, 'couch').find((c) => c.dataset['columnStart'] === '5')!;
    expect(row15.dataset['state']).toBe('unavailable');
  });

  it('selects, lists and limits seats', async () => {
    const fixture = await setup();
    const el = fixture.nativeElement as HTMLElement;
    const seat = (row: number, col: number) =>
      q(el, 'seat').find((s) => s.dataset['row'] === String(row) && s.dataset['column'] === String(col))!;
    seat(7, 12).click();
    seat(7, 11).click();
    q(el, 'couch')[0].click();
    await fixture.whenStable();
    expect(q(el, 'selected-seats-count')[0].textContent!.trim()).toBe('Selected seats: 4');
    expect(q(el, 'selected-seats-row').map((r) => r.textContent!.trim())).toEqual(['Row 7: 11, 12', 'Row 15: 1-2']);
    seat(3, 7).click();
    await fixture.whenStable();
    expect(seat(3, 7).dataset['state']).toBe('unavailable');
  });
});
